USE aerosoft360_rebuild;
CREATE TABLE IF NOT EXISTS employees (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_no VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,department VARCHAR(80) NOT NULL,designation VARCHAR(80) NOT NULL,basic_salary DECIMAL(18,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payroll_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(255) NOT NULL UNIQUE,period_start DATE NOT NULL,period_end DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',gross_total DECIMAL(18,2) NOT NULL DEFAULT 0,deduction_total DECIMAL(18,2) NOT NULL DEFAULT 0,net_total DECIMAL(18,2) NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payroll_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payroll_run_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,basic_salary DECIMAL(18,2) NOT NULL,allowances DECIMAL(18,2) NOT NULL DEFAULT 0,overtime DECIMAL(18,2) NOT NULL DEFAULT 0,incentive DECIMAL(18,2) NOT NULL DEFAULT 0,epf_employee DECIMAL(18,2) NOT NULL DEFAULT 0,other_deductions DECIMAL(18,2) NOT NULL DEFAULT 0,net_salary DECIMAL(18,2) NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY payroll_employee(payroll_run_id,employee_id),FOREIGN KEY(payroll_run_id) REFERENCES payroll_runs(id) ON DELETE CASCADE,FOREIGN KEY(employee_id) REFERENCES employees(id)) ENGINE=InnoDB;
ON DUPLICATE KEY UPDATE name=VALUES(name),department=VALUES(department),designation=VALUES(designation),basic_salary=VALUES(basic_salary),updated_at=NOW();
ON DUPLICATE KEY UPDATE allowances=VALUES(allowances),overtime=VALUES(overtime),incentive=VALUES(incentive),epf_employee=VALUES(epf_employee),other_deductions=VALUES(other_deductions),net_salary=VALUES(net_salary),updated_at=NOW();
